// ── Flatten Salesforce Report (hiring) ────────────────────────────────────
// Turns one Analytics API report response into one n8n item per Account row.
// Uses reportMetadata.detailColumns order + factMap["T!T"].rows[].dataCells.
// Reads cell.value (not HTML label). Aliases report keys → Account API names
// so Prepare / Map / Update keep using Id, Name, Website, Is_Hiring_Engineers__c, …
// Code node mode: "Run Once for All Items".

const REPORT_TO_SF = {
  ACCOUNT_ID: "Id",
  "ACCOUNT.NAME": "Name",
  ADDRESS1_STATE: "BillingState",
  URL: "Website",
  "Account.LinkedIn__c": "LinkedIn__c",
  DESCRIPTION: "Description",
  "Account.Is_Hiring_Engineers__c": "Is_Hiring_Engineers__c",
  "Account.Hiring_Score__c": "Hiring_Score__c",
  "Account.Careers_Page__c": "Careers_Page__c",
  "Account.Open_Job_Openings__c": "Open_Job_Openings__c",
  "Account.Open_Job_Openings_Count__c": "Open_Job_Openings_Count__c",
};

function cellValue(cell) {
  if (cell == null || typeof cell !== "object") return cell == null ? null : cell;
  return Object.prototype.hasOwnProperty.call(cell, "value") ? cell.value : null;
}

function firstRecordId(cells) {
  for (const cell of cells) {
    if (cell && cell.recordId) return cell.recordId;
  }
  return "";
}

const root = $input.first().json;
const columns = (root.reportMetadata && root.reportMetadata.detailColumns) || [];
const factMap = root.factMap || {};
const bucket = factMap["T!T"] || factMap["T|T"] || {};
const rows = bucket.rows || [];

if (!columns.length || !rows.length) {
  return [];
}

return rows
  .map((row) => {
    const cells = row.dataCells || [];
    const raw = {};
    columns.forEach((col, i) => {
      raw[col] = cellValue(cells[i]);
    });

    const out = { ...raw };
    for (const [from, to] of Object.entries(REPORT_TO_SF)) {
      if (Object.prototype.hasOwnProperty.call(raw, from)) {
        out[to] = raw[from];
      }
    }

    const id = out.Id || raw.ACCOUNT_ID || firstRecordId(cells) || "";
    if (id) out.Id = id;

    return { json: out };
  })
  .filter((item) => item.json.Id && String(item.json.Name || item.json["ACCOUNT.NAME"] || "").trim());

// ── Prepare Requests (Salesforce) ─────────────────────────────────────────
// Runs once per Account row (from Flatten Report aliases, or SOQL/CSV test
// data). Builds the request bodies/queries for all four hiring sources so the
// HTTP nodes stay simple. Reads Account API names (Name, Website, BillingState)
// with report / CSV header fallbacks.
// Code node mode: "Run Once for Each Item".

const MODEL = "claude-haiku-4-5-20251001";

const TARGET_ROLES = [
  "software engineer", "software developer", "backend engineer", "frontend engineer",
  "full stack", "fullstack", "devops", "platform engineer", "site reliability", "sre",
  "qa engineer", "quality assurance", "automation engineer", "test engineer", "sdet",
  "mobile developer", "ios developer", "android developer", "data engineer", "data scientist",
  "ml engineer", "ai engineer", "machine learning", "nlp engineer", "bi engineer",
  "business intelligence", "data analyst", "ux designer", "ui designer", "product designer",
  "cloud engineer", "infrastructure engineer", "security engineer", "cybersecurity",
  "engineering manager", "director of engineering", "vp of engineering", "vp engineering",
  "tech lead", "technical lead", "staff engineer",
];

const c = $input.item.json;
const company = String(c["Name"] || c["Account Name"] || c["company_name"] || "").trim();
const website = String(c["Website"] || c["company_website"] || "").trim();
const liUrl   = String(c["LinkedIn__c"] || c["LinkedIn"] || c["company_linkedin_url"] || "").trim();
const state   = String(c["BillingState"] || c["Billing State/Province"] || c["state"] || "").trim();

let liJobs = "";
if (liUrl.includes("linkedin.com/company/")) {
  const slug = liUrl.replace(/\/+$/, "").split("/company/")[1].split("/")[0];
  liJobs = `https://www.linkedin.com/company/${slug}/jobs/`;
}

const base = website.replace(/\/+$/, "");
const careersHints = base ? `${base}/careers, ${base}/jobs, ${base}/join-us` : "search for careers page";

let domain = "";
if (website) domain = website.replace("https://", "").replace("http://", "").split("/")[0];

const prompt = `You are a sales research assistant for AssureSoft, a nearshore software engineering company.

Find CURRENT open engineering/tech job postings at this company.
A company actively hiring engineers is our strongest buying signal.

COMPANY: ${company}
WEBSITE: ${website || "unknown"}
STATE: ${state || "US"}
LINKEDIN JOBS: ${liJobs || "search for it"}
CAREERS PAGE: ${careersHints}

Search ALL of these — try every source:
1. LinkedIn Jobs page: ${liJobs || `search linkedin.com for "${company}" jobs`}
2. Company careers page: ${careersHints}
3. Indeed.com: search "${company} software engineer" or "${company} developer"
4. Web: "${company} engineering jobs 2025" or "${company} hiring engineers"

TARGET ROLES — report ANY of these:
Software Engineer/Developer, Backend/Frontend/Full Stack, DevOps/Platform/SRE,
QA/Automation/Test Engineer, SDET, Mobile (iOS/Android), Data/ML/AI Engineer,
BI Engineer, UX/UI Designer, Cloud/Security Engineer, Engineering Manager,
Director/VP Engineering, Tech Lead, Staff Engineer

Return ONLY valid JSON — no markdown, no explanation:
{
  "is_hiring_engineers": "<Yes | No | Unknown>",
  "open_roles": "<comma-separated role titles actually found>",
  "open_roles_count": <integer — engineering roles only>,
  "hiring_source": "<LinkedIn | Careers Page | Indeed | Web Search | Multiple | None>",
  "careers_page_url": "<direct URL to careers page if found, else empty>",
  "linkedin_jobs_url": "<confirmed linkedin jobs URL, else empty>",
  "indeed_jobs_url": "<indeed URL for company if found, else empty>",
  "most_recent_posting": "<date or 'within last 30 days' or 'unknown'>",
  "tech_stack_hints": "<technologies from job descriptions e.g. 'Python, AWS, React'>",
  "notes": "<one sentence context>"
}

Rules:
- Only report roles you ACTUALLY found — never guess or fabricate
- Count ONLY engineering/tech roles — ignore sales/marketing/finance
- If LinkedIn blocks, try Indeed and careers page instead`;

const claudeBody = {
  model: MODEL,
  max_tokens: 800,
  tools: [{ type: "web_search_20250305", name: "web_search" }],
  messages: [{ role: "user", content: prompt }],
};

const jsearchQuery = `"${company}" (engineer OR developer OR devops OR QA OR "data engineer")`;

const theirstackBody = {
  page: 0,
  limit: 25,
  order_by: [{ desc: true, field: "discovered_at" }],
  job_title_or: TARGET_ROLES.slice(0, 10),
  company_name_or: [company],
  ...(domain ? { company_domain_or: [domain] } : {}),
};

const apolloBody = {
  q_organization_name: company,
  organization_domains: domain ? [domain] : [],
  page: 1,
  per_page: 1,
};

return {
  json: {
    ...c,
    _company: company,
    _website: website,
    _state: state,
    _domain: domain,
    _liJobs: liJobs,
    _claudeBody: claudeBody,
    _jsearchQuery: jsearchQuery,
    _theirstackBody: theirstackBody,
    _apolloBody: apolloBody,
  },
};

// ── Merge & Score ─────────────────────────────────────────────────────────
// Ports the Python per-source parsing + merge_results() scoring. Reads the four
// HTTP node outputs (each may have failed → guarded) and the Prepare node, then
// emits the enrichment columns keyed by "Account ID" for the Sheets update.
// Code node mode: "Run Once for Each Item".

const TARGET_ROLES = [
  "software engineer", "software developer", "backend engineer", "frontend engineer",
  "full stack", "fullstack", "devops", "platform engineer", "site reliability", "sre",
  "qa engineer", "quality assurance", "automation engineer", "test engineer", "sdet",
  "mobile developer", "ios developer", "android developer", "data engineer", "data scientist",
  "ml engineer", "ai engineer", "machine learning", "nlp engineer", "bi engineer",
  "business intelligence", "data analyst", "ux designer", "ui designer", "product designer",
  "cloud engineer", "infrastructure engineer", "security engineer", "cybersecurity",
  "engineering manager", "director of engineering", "vp of engineering", "vp engineering",
  "tech lead", "technical lead", "staff engineer",
];

const TECH_KEYWORDS = [
  "Python", "Java", "JavaScript", "TypeScript", "Go", "Rust", "C#", ".NET", "React", "Vue",
  "Angular", "Node.js", "Swift", "Kotlin", "AWS", "Azure", "GCP", "Kubernetes", "Docker",
  "Terraform", "Databricks", "Spark", "Kafka", "Airflow", "PostgreSQL", "MongoDB", "Redis",
  "MySQL", "GraphQL", "REST", "microservices", "Agile", "Scrum", "CI/CD",
];

function nodeJson(name) {
  try { return $(name).item.json; } catch (e) { return null; }
}
function hasRole(title) {
  const t = String(title || "").toLowerCase();
  return TARGET_ROLES.some((r) => t.includes(r));
}

const company = $("Prepare Requests").item.json;
const companyName = String(company["Account Name"] || company._company || "");
const results = [];

// ── SOURCE 1 — Claude web search ──────────────────────────────────────────
try {
  const resp = nodeJson("Claude Web Search");
  if (resp && !resp.error && Array.isArray(resp.content)) {
    const text = resp.content
      .filter((b) => b && b.type === "text" && b.text)
      .map((b) => b.text)
      .join(" ");
    const m = text.match(/\{[\s\S]*?\}/);
    if (m) {
      const d = JSON.parse(m[0]);
      results.push({
        source: "claude_web",
        is_hiring: String(d.is_hiring_engineers || "Unknown").trim(),
        roles: String(d.open_roles || "").trim(),
        count: parseInt(d.open_roles_count || 0) || 0,
        careers_page_url: String(d.careers_page_url || "").trim(),
        linkedin_jobs_url: String(d.linkedin_jobs_url || "").trim(),
        indeed_jobs_url: String(d.indeed_jobs_url || "").trim(),
        recent_posting: String(d.most_recent_posting || "").trim(),
        tech_stack: String(d.tech_stack_hints || "").trim(),
        notes: String(d.notes || "").trim(),
      });
    }
  }
} catch (e) { /* skip source on parse failure */ }

// ── SOURCE 2 — JSearch (Indeed via RapidAPI) ──────────────────────────────
try {
  const resp = nodeJson("JSearch");
  const jobs = resp && Array.isArray(resp.data) ? resp.data : [];
  const nameKey = companyName.toLowerCase().slice(0, 6);
  const relevant = [];
  for (const job of jobs) {
    const title = String(job.job_title || "").toLowerCase();
    const emp = String(job.employer_name || "").toLowerCase();
    if (nameKey && emp.includes(nameKey) && hasRole(title)) relevant.push(job.job_title || "");
  }
  const roles = [...new Set(relevant)].slice(0, 15);
  if (jobs.length || roles.length) {
    results.push({
      source: "jsearch",
      is_hiring: roles.length ? "Yes" : jobs.length ? "No" : "Unknown",
      roles: roles.join(", "),
      count: roles.length,
      careers_page_url: "",
      linkedin_jobs_url: "",
      indeed_jobs_url: "https://www.indeed.com/jobs?q=" + encodeURIComponent(companyName),
      recent_posting: "within last 30 days",
      tech_stack: "",
      notes: `JSearch: ${jobs.length} total postings, ${roles.length} eng roles`,
    });
  }
} catch (e) { /* skip */ }

// ── SOURCE 3 — Theirstack ─────────────────────────────────────────────────
try {
  const resp = nodeJson("Theirstack");
  const jobs = resp && Array.isArray(resp.data) ? resp.data : [];
  const roles = [...new Set(jobs.map((j) => j.job_title).filter(Boolean))];
  const tech = {};
  for (const job of jobs) {
    const desc = String(job.job_description || "").toLowerCase();
    for (const kw of TECH_KEYWORDS) {
      if (desc.includes(kw.toLowerCase())) tech[kw] = (tech[kw] || 0) + 1;
    }
  }
  const topTech = Object.entries(tech).sort((a, b) => b[1] - a[1]).slice(0, 8).map((x) => x[0]).join(", ");
  if (jobs.length) {
    results.push({
      source: "theirstack",
      is_hiring: roles.length ? "Yes" : "No",
      roles: roles.slice(0, 15).join(", "),
      count: roles.length,
      careers_page_url: jobs[0].apply_url || "",
      linkedin_jobs_url: "",
      indeed_jobs_url: "",
      recent_posting: String(jobs[0].discovered_at || "").slice(0, 7),
      tech_stack: topTech,
      notes: `Theirstack: ${jobs.length} eng roles`,
    });
  }
} catch (e) { /* skip */ }

// ── SOURCE 4 — Apollo.io ──────────────────────────────────────────────────
try {
  const resp = nodeJson("Apollo");
  const orgs = resp ? resp.organizations || resp.accounts || [] : [];
  if (orgs && orgs.length) {
    const org = orgs[0];
    const postings = org.job_postings || [];
    const eng = postings.map((j) => j.title || "").filter((t) => hasRole(t));
    const techNames = org.technology_names || [];
    results.push({
      source: "apollo",
      is_hiring: eng.length ? "Yes" : postings.length ? "No" : "Unknown",
      roles: [...new Set(eng.slice(0, 15))].join(", "),
      count: eng.length,
      careers_page_url: org.organization_job_page_url || "",
      linkedin_jobs_url: "",
      indeed_jobs_url: "",
      recent_posting: postings[0] && postings[0].posted_at ? String(postings[0].posted_at).slice(0, 7) : "",
      tech_stack: techNames.slice(0, 10).join(", "),
      notes: `Apollo: ${org.estimated_num_employees || ""} employees, ${postings.length} postings`,
    });
  }
} catch (e) { /* skip */ }

// ── merge_results() ───────────────────────────────────────────────────────
function merge(results) {
  if (!results.length) {
    return {
      is_hiring_engineers: "Unknown", open_roles: "", open_roles_count: 0, hiring_score: 0,
      hiring_urgency: "Unknown", hiring_source: "None", careers_page_url: "", linkedin_jobs_url: "",
      indeed_jobs_url: "", most_recent_posting: "", tech_stack_hints: "", hiring_notes: "", data_confidence: "Low",
      _hiring_status: "error",
      _hiring_error: "no hiring sources returned usable data",
      _sources_ok: 0,
    };
  }
  const allRoles = new Set(), sources = [], allTech = new Set(), notes = [];
  let anyYes = false, anyNo = false;
  const fields = { careers_page_url: "", linkedin_jobs_url: "", indeed_jobs_url: "", recent_posting: "" };
  for (const r of results) {
    sources.push(r.source);
    if (r.is_hiring === "Yes") anyYes = true;
    else if (r.is_hiring === "No") anyNo = true;
    for (let role of String(r.roles || "").split(",")) { role = role.trim(); if (role) allRoles.add(role); }
    for (const f of Object.keys(fields)) { if (r[f] && !fields[f]) fields[f] = r[f]; }
    for (let t of String(r.tech_stack || "").split(",")) { t = t.trim(); if (t) allTech.add(t); }
    if (r.notes) notes.push(`[${r.source}] ${r.notes}`);
  }
  const isHiring = anyYes ? "Yes" : anyNo ? "No" : "Unknown";
  const total = allRoles.size;
  const n = results.length;
  const confidence = n >= 3 ? "High" : n === 2 ? "Medium" : "Low";
  let score = 0;
  if (isHiring === "Yes") {
    if (total >= 8) score = 5;
    else if (total >= 5) score = 4;
    else if (total >= 3) score = 3;
    else if (total >= 2) score = 2;
    else score = 1;
    if (n >= 2) score = Math.min(5, score + 1);
  }
  const urgency = score >= 4 ? "Hot" : score >= 2 ? "Warm" : score === 1 ? "Cold" : "Unknown";
  return {
    is_hiring_engineers: isHiring,
    open_roles: [...allRoles].sort().slice(0, 20).join(", "),
    open_roles_count: total,
    hiring_score: score,
    hiring_urgency: urgency,
    hiring_source: [...new Set(sources)].sort().join(" + "),
    careers_page_url: fields.careers_page_url,
    linkedin_jobs_url: fields.linkedin_jobs_url,
    indeed_jobs_url: fields.indeed_jobs_url,
    most_recent_posting: fields.recent_posting,
    tech_stack_hints: [...allTech].sort().slice(0, 12).join(", "),
    hiring_notes: notes.join(" | ").slice(0, 300),
    data_confidence: confidence,
    _hiring_status: "done",
    _hiring_error: "",
    _sources_ok: n,
  };
}

const merged = merge(results);

// Keep the original row columns (minus internal _-prefixed helpers), then
// overlay the enrichment columns. Works for both the Sheets update (auto-map
// matches on "Account ID") and the CSV download in the test workflow.
const clean = {};
for (const [k, v] of Object.entries(company)) {
  if (!k.startsWith("_")) clean[k] = v;
}

return { json: { ...clean, ...merged } };

// ── Map to Salesforce (hiring) ────────────────────────────────────────────
// Maps the hiring enrichment output onto Account fields and diffs against the
// values read from Salesforce, so the PATCH body contains nothing but the
// fields that actually changed. Empty enrichment values are skipped — they
// never blank out an existing Salesforce value.
//
// Eligibility gate: field PATCHes only run when _hiring_status === "done" AND
// at least one confirmed signal exists (Yes/No hiring answer, open eng roles,
// careers/LinkedIn URL, or hiring_score > 0). Failed/empty research never
// writes hiring fields.
//
// Cohort comes from the Salesforce report (not SOQL / Skip Enriched). Current
// Account values are aliased from report columns in Flatten Report.
//
// Custom fields written on Account:
//
//   Is_Hiring_Engineers__c      ← is_hiring_engineers  (Yes/No/Unknown, text)
//   Hiring_Score__c             ← hiring_score         (Number, 0–5)
//   LinkedIn__c                 ← linkedin_jobs_url    (URL/text)
//   Careers_Page__c             ← careers_page_url     (URL/text)
//   Open_Job_Openings__c        ← open_roles           (text — role titles)
//   Open_Job_Openings_Count__c  ← open_roles_count     (Number)
//
// Description: enrichment blobs are NOT written. On an eligible run, any legacy
// automation blocks ("Hiring engineers:…[Hiring|Auto-enriched …]") are stripped
// so Description returns to human/company content only.
//
// Note: urgency / confidence stay in the weekly email digest only — no dedicated
// Salesforce fields for those in this org.
// Code node mode: "Run Once for Each Item".

const j = $input.item.json;
const changes = {};
const str = (v) => String(v == null ? "" : v).trim();

function setIfChanged(field, value) {
  if (value == null || value === "") return;
  const current = j[field];
  if (typeof value === "number") {
    const cur = current == null || current === "" ? null : Number(current);
    if (cur !== value) changes[field] = value;
  } else if (typeof value === "boolean") {
    if (Boolean(current) !== value) changes[field] = value;
  } else if (str(current) !== str(value)) {
    changes[field] = str(value);
  }
}

const hiringStatus = str(j._hiring_status);
const hiringError = str(j._hiring_error);
const hiring = str(j.is_hiring_engineers) || "Unknown";
const openRoles = str(j.open_roles);
const rolesCount = parseInt(j.open_roles_count, 10) || 0;
const score = parseInt(j.hiring_score, 10) || 0;
const urgency = str(j.hiring_urgency);
const careersUrl = str(j.careers_page_url);
const linkedinUrl = str(j.linkedin_jobs_url);
const hiringSource = str(j.hiring_source);
const confidence = str(j.data_confidence);

const confirmedBits = [];
if (hiring === "Yes" || hiring === "No") confirmedBits.push("is_hiring_engineers");
if (rolesCount > 0) confirmedBits.push("open_roles_count");
if (score > 0) confirmedBits.push("hiring_score");
if (careersUrl) confirmedBits.push("careers_page_url");
if (linkedinUrl) confirmedBits.push("linkedin_jobs_url");

const researchOk = hiringStatus === "done";
const hasConfirmed = confirmedBits.length > 0;
const eligible = researchOk && hasConfirmed;

let skipReason = "";
if (!researchOk) {
  skipReason = hiringError || `research status=${hiringStatus || "missing"}`;
} else if (!hasConfirmed) {
  skipReason = "no confirmed hiring signals (Yes/No, roles, score, careers/LinkedIn URL)";
}

if (!eligible) {
  return {
    json: {
      Id: j.Id,
      Name: j.Name,
      _changes: {},
      _changedFields: "",
      _hasChanges: false,
      _eligible: false,
      _skipReason: skipReason,
      _hiring_status: hiringStatus || "error",
      _hiring_error: hiringError,
      _confirmedFields: "",
      is_hiring_engineers: hiring,
      hiring_score: score,
      hiring_urgency: urgency,
      open_roles: openRoles,
      open_roles_count: rolesCount,
      hiring_source: hiringSource,
      data_confidence: confidence,
      careers_page_url: careersUrl,
      linkedin_jobs_url: linkedinUrl,
    },
  };
}

// ── Hiring-signal fields ──────────────────────────────────────────────────
setIfChanged("Is_Hiring_Engineers__c", hiring);
setIfChanged("Hiring_Score__c", score);
setIfChanged("LinkedIn__c", linkedinUrl);
setIfChanged("Careers_Page__c", careersUrl);
setIfChanged("Open_Job_Openings__c", openRoles);
setIfChanged("Open_Job_Openings_Count__c", rolesCount);

// ── Description cleanup only (no new enrichment text) ─────────────────────
const current = str(j.Description);
const cleaned = current
  .replace(
    /(^|\n)Hiring engineers:[\s\S]*?\[(?:Hiring|Auto)-enriched \d{4}-\d{2}-\d{2}\]/g,
    "$1"
  )
  .replace(/\n{3,}/g, "\n\n")
  .trim();
if (cleaned !== current) changes.Description = cleaned;

return {
  json: {
    Id: j.Id,
    Name: j.Name,
    _changes: changes,
    _changedFields: Object.keys(changes).sort().join(", "),
    _hasChanges: Object.keys(changes).length > 0,
    _eligible: true,
    _skipReason: "",
    _hiring_status: "done",
    _hiring_error: "",
    _confirmedFields: confirmedBits.join(", "),
    is_hiring_engineers: hiring,
    hiring_score: score,
    hiring_urgency: urgency,
    open_roles: openRoles,
    open_roles_count: rolesCount,
    hiring_source: hiringSource,
    data_confidence: confidence,
    careers_page_url: careersUrl,
    linkedin_jobs_url: linkedinUrl,
  },
};

// ── Build Run Summary Email ───────────────────────────────────────────────
// Connected from Map to Salesforce (after the Has Changes → Update Account
// branch in connection order) so PATCHes finish first under executionOrder v1.
// Lists enriched companies, skips, and failed PATCH bodies.
// Code node mode: "Run Once for All Items".

function safeAll(name) {
  try {
    return $(name).all().map((i) => i.json);
  } catch (e) {
    return [];
  }
}

const mapped = safeAll("Map to Salesforce");
const patched = safeAll("Update Account");

const attempted = mapped.filter((m) => m._eligible && m._hasChanges);
const skipped = mapped.filter((m) => !m._eligible);
const noOp = mapped.filter((m) => m._eligible && !m._hasChanges);

// Has Changes → Update Account preserves item order; pair by index.
const patchFailures = [];
const enrichedList = [];
for (let i = 0; i < attempted.length; i++) {
  const m = attempted[i];
  const p = patched[i];
  if (p && p.error) {
    const msg = String(
      (p.error.message || p.error.description || p.error) || "PATCH failed"
    ).slice(0, 300);
    patchFailures.push({
      name: m.Name || "?",
      id: m.Id || "",
      message: msg,
      body: JSON.stringify(m._changes || {}).slice(0, 400),
    });
  } else {
    enrichedList.push(m);
  }
}

const lines = [];
lines.push("Hi team,");
lines.push("");
lines.push("Weekly Salesforce Account hiring-signal enrichment summary:");
lines.push("");
lines.push(`  • Researched:  ${mapped.length}`);
lines.push(`  • Enriched:    ${enrichedList.length}`);
lines.push(`  • Unchanged:   ${noOp.length} (eligible, Salesforce already matched)`);
lines.push(`  • Skipped:     ${skipped.length} (ineligible — will retry next week)`);
lines.push(`  • PATCH fail:  ${patchFailures.length}`);
lines.push("");

if (enrichedList.length) {
  lines.push("── Companies enriched ──");
  for (const m of enrichedList) {
    const bits = [
      m.is_hiring_engineers ? `hiring: ${m.is_hiring_engineers}` : "",
      m.hiring_score != null ? `score ${m.hiring_score}` : "",
      m.hiring_urgency && m.hiring_urgency !== "Unknown"
        ? m.hiring_urgency
        : "",
      m.open_roles_count ? `${m.open_roles_count} eng roles` : "",
      m.hiring_source && m.hiring_source !== "None"
        ? `via ${m.hiring_source}`
        : "",
    ]
      .filter(Boolean)
      .join(" | ");
    lines.push(
      `- ${m.Name || "?"} (${m.Id || "no Id"})${bits ? ` — ${bits}` : ""}`
    );
    if (m._changedFields) lines.push(`    fields: ${m._changedFields}`);
  }
  lines.push("");
}

if (skipped.length) {
  lines.push("── Skipped (marker NOT written; will retry) ──");
  for (const m of skipped) {
    lines.push(
      `- ${m.Name || "?"} (${m.Id || "no Id"}): ${m._skipReason || m._hiring_error || "ineligible"}`
    );
  }
  lines.push("");
}

if (patchFailures.length) {
  lines.push("── PATCH failures ──");
  for (const f of patchFailures) {
    lines.push(`- ${f.name} (${f.id}): ${f.message}`);
    if (f.body) lines.push(`    body: ${f.body}`);
  }
  lines.push("");
}

if (noOp.length) {
  lines.push(`── Eligible but unchanged (${noOp.length}) ──`);
  for (const m of noOp) {
    lines.push(`- ${m.Name || "?"} (${m.Id || "no Id"})`);
  }
  lines.push("");
}

lines.push("— Automations (n8n)");

const hasProblems = skipped.length > 0 || patchFailures.length > 0;
const subject = hasProblems
  ? `⚠️ Hiring Account enrichment — ${enrichedList.length} enriched, ${skipped.length} skipped, ${patchFailures.length} PATCH fail`
  : `✅ Hiring Account enrichment — ${enrichedList.length} companies enriched`;

return [
  {
    json: {
      subject,
      body: lines.join("\n"),
      hasAttachment: false,
      outcome: hasProblems ? "partial" : "success",
      enrichedCount: enrichedList.length,
      skippedCount: skipped.length,
      patchFailCount: patchFailures.length,
      researchedCount: mapped.length,
    },
  },
];

// ── Build Failure Email ───────────────────────────────────────────────────
// Fires only when the workflow HARD-fails, via the Error Trigger. Produces the
// failure subject/body for the shared Send Email node. No attachment.
// Code node mode: "Run Once for All Items".

const info = ($input.first() && $input.first().json) || {};
const wf =
  (info.workflow && info.workflow.name) ||
  "Salesforce Account Enrichment (Hiring signals, weekly)";
const exec = info.execution || {};
const errMsg =
  (exec.error && (exec.error.message || exec.error)) || "Unknown error";
const lastNode = exec.lastNodeExecuted || "unknown node";
const url = exec.url || "";

const subject = `⚠️ Hiring Account enrichment FAILED — ${wf}`;

const parts = [
  "Hi team,",
  "",
  "The weekly Salesforce hiring-signal enrichment run did NOT complete.",
  "Accounts researched in a partial run (if any) were not summarised by the success email.",
  "",
  `  • Workflow:  ${wf}`,
  `  • Failed at: ${lastNode}`,
  `  • Error:     ${String(errMsg).slice(0, 300)}`,
];
if (url) parts.push(`  • Execution: ${url}`);
parts.push("");
parts.push(
  "Check n8n Executions, Anthropic/JSearch/Theirstack/Apollo quotas, and the Salesforce credential/host."
);
parts.push("Ineligible accounts are not marked enriched and will retry next week.");
parts.push("");
parts.push("— Automations (n8n)");

return [
  {
    json: {
      subject,
      body: parts.join("\n"),
      hasAttachment: false,
      outcome: "failure",
    },
  },
];
